add(532,'الشيخ، فتأمّله.','это. Поразмысли над этим.',False,True)
add(532,'وقولهم: «فني من لم يكن، وبقي من لم يزل»، إن أرادوا به: فني في الوجود الخارجيّ، فهذا مكابرة. وإن أرادوا به أنّه فني في الشهود، فهذا نقص في الإيمان والتوحيد كما تقرّر. وإن أرادوا به أنّه فني في القصد والإرادة والمحبّة، فهذا هو الحقّ، وهو الفناء عن إرادة السوى وقصده ومحبّته.','Их слова: «Исчез тот, кого не было, и остался Тот, Кто был всегда». Если они подразумевают исчезновение во внешнем существовании, то это упрямое отрицание очевидного. Если подразумевают исчезновение из созерцания, то это недостаток веры и единобожия, как уже установлено. Если же подразумевают исчезновение из направленности стремления, воли и любви, то это истина: фана от желания иного, стремления к нему и любви к нему.')
add(532,'قوله: (هذا توحيد الخاصّة، الذي يصحّ بعلم الفناء، ويصفو في علم الجمع، ويجذب إلى توحيد أرباب الجمع)، يعني: توحيد المتوسّطين الذين ارتفعوا عن العامّة، ولم يصلوا إلى منزل خاصّة الخاصّة.','Его слова: «Это единобожие избранных, которое становится правильным благодаря знанию фана, очищается в знании собранности и влечёт к единобожию людей собранности». Он имеет в виду единобожие находящихся посередине: они поднялись над обычными людьми, но не достигли обители избранных из избранных.')
add(532,'قوله: (يصحّ بعلم الفناء)، ولم يقل: بحقيقة الفناء، لأنّ درجة العلم في هذا السلوك قبل درجة الحال والمعرفة، وصاحب هذه الدرجة متوسّط لم يبلغ الغاية، وحال الفناء لصاحب الدرجة الثالثة.','Его слова: «Становится правильным благодаря знанию фана». Он не сказал: действительностью фана, — потому что на этом пути ступень знания предшествует ступени состояния и познания. Обладатель этой ступени находится посередине, ещё не достиг предела, а состояние фана принадлежит обладателю третьей ступени.')
add(532,'وكذلك قوله: (ويصفو في علم الجمع)، فإنّ علم الجمع قبل حال الجمع، كما تقدّم في بابه.','Так же и слова: «Очищается в знании собранности». Ведь знание собранности предшествует состоянию собранности, как уже говорилось в соответствующей главе.')
add(532,'قوله: (ويجذب إلى توحيد أرباب الجمع)، يريد: أنّ هذا المقام يجذب أهله إلى توحيد الفريق الذين فوقهم، وهم أصحاب الجمع.','Его слова: «И влечёт к единобожию людей собранности». Он хочет сказать, что эта стоянка влечёт её обладателей к единобожию тех, кто выше них, — людей собранности.')
add(532,'وقد تقدّم ذكر الجمع، ولم يحصل به الشفاء. ونحن الآن ذاكرون حقيقته وأقسامه، والصحيح منه والمعلول. والله المستعان.','О собранности уже говорилось, но это не дало полного удовлетворения. Теперь мы изложим её сущность, разновидности, то, что в ней правильно и что имеет изъяны. К Аллаху обращаются за помощью.')
add(532,'الجمع في اللغة: الضمّ. والاجتماع: الانضمام. والتفريق: ضدّه. وأمّا في','В языке «джам» — собирание, соединение; «иджтима» — соединение вместе; различение — противоположность этому. А в',False)
add(533,'اصطلاح القوم: فهو شخوص البصيرة إلى من صدرت عنه المتفرّقات كلّها. وهو ثلاثة أنواع: جمع وجود ـ وهو جمع الزنادقة من أهل الاتّحاد ـ وجمع شهود، وجمع قصود. فإذا تحرّرت هذه الأقسام تحرّر الجمع الصحيح والفاسد.','терминологии этих людей это устремлённость духовной зоркости к Тому, от Кого исходят все разрозненные вещи. Он бывает трёх видов: собранность существования — собранность еретиков из сторонников единения; собранность созерцания и собранность стремления. Когда эти разновидности будут чётко разграничены, станут ясны правильная и порочная собранность.',False,True)
add(533,'وكذلك الفرق ينقسم إلى صحيح وفاسد، أعني إلى مطلوب في السلوك وإلى قاطع عن السلوك. فالفرق ثلاثة أنواع: فرق طبعيّ حيوانيّ، وفرق إسلاميّ، وفرق إيمانيّ، فهذه أقسام ستّة للجمع والفرق.','Так же и различение делится на правильное и порочное, то есть на требуемое в духовном пути и прерывающее его. Различение бывает трёх видов: естественное, животное различение; исламское различение и различение веры. Итак, у собранности и различения шесть разновидностей.')
add(533,'فنذكر أنواع الفرق أوّلًا، إذ بها تعرف أنواع الجمع.','Сначала рассмотрим виды различения, поскольку через них познаются виды собранности.')
add(533,'فأمّا الفرق الطبعيّ الحيوانيّ، فهو التفريق بمجرّد الطبع والميل، فيفرّق بين ما يفعله ولا يفعله بطبعه وهواه. وهذا فرق الحيوانات وأشباهها من بني آدم، فالمعيار: ميل طبعه، ونفرة طبعه. والمشركون والكفّار وأهل الظلم والعدوان واقفون مع هذا الفرق.','Что касается естественного, животного различения, то это разграничение лишь по природной склонности и влечению: человек различает, что ему делать, а чего не делать, по своему естеству и страсти. Таково различение животных и подобных им сынов Адама. Мерило здесь — влечение его природы и её отвращение. На этом различении останавливаются многобожники, неверующие, несправедливые и враждебные.')
add(533,'وأمّا الفرق الإسلاميّ، فهو الفرق بين ما شرعه الله وأمر به وأحبّه ورضيه، وبين ما نهى عنه وكرهه ومقت فاعله. وهذا الفرق من لم يكن من أهله لم يشمّ رائحة الإسلام البتّة. وقد حكى الله سبحانه عن أهل الفرق الطبعيّ أنّهم أنكروا هذا الفرق، فشهدوا الجمع بين المأمور والمحظور، فقالوا: {إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا} [البقرة: 275] لا فرق بينهما، وقالوا: الميتة','Исламское же различение — различение между тем, что Аллах узаконил, велел, полюбил и одобрил, и тем, что Он запретил, возненавидел и за что возненавидел совершающего это. Не обладающий таким различением вовсе не ощутил запаха ислама. Аллах, пречистый, рассказал о приверженцах естественного различения, что они отвергли это различение и усмотрели объединение веленного и запретного. Они сказали: {إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا} — «Торговля подобна ростовщичеству» [«Аль-Бакара», 2:275], — между ними нет различия. И сказали: «Мертвечина',False)
add(534,'مثل المذكّاة، لا فرق بينهما، وقالوا: الحلال والحرام شيء واحد. فهذا جمعهم وذاك فرقهم.','подобна заколотому по правилам животному: между ними нет различия». Они сказали: «Дозволенное и запретное — одно». Такова их собранность, а выше было их различение.',False,True)
add(534,'فصل','Раздел')
add(534,'فهذا فرق يتعلّق بالأعمال.','Это различение относится к деяниям.')
add(534,'وأمّا الفرق الإيمانيّ الذي يتعلّق بمسائل القضاء والقدر، فهو التمييز الإيمانيّ بين فعل الحقّ سبحانه وأفعال العباد. فيؤمن بأنّ الله وحده خالق كلّ شيء، وليس في الكون إلّا ما هو واقع بمشيئته وقدرته وخلقه؛ ومع ذلك يؤمن بأنّ العبد فاعل لأفعاله حقيقة، وهي صادرة عن قدرته ومشيئته قائمة به، وهو فاعل لها على الحقيقة. فيشهد تفرّد الربّ بالخلق والتقدير، ووقوع أفعال العباد منهم بقدرهم ومشيئتهم، والله خالق ذلك كلّه.','Различение веры, относящееся к вопросам решения и предопределения, — это различение посредством веры между действием Истинного, пречистого, и действиями рабов. Человек верит, что один Аллах — Творец всякой вещи и что всё в мироздании происходит по Его воле, могуществу и творению. Вместе с тем он верит, что раб действительно совершает свои действия: они исходят из его способности и воли, осуществляются в нём и он совершает их в действительности. Он созерцает единоличность Господа в творении и предопределении, а также то, что действия рабов совершаются ими посредством их способностей и воли; всё это создал Аллах.')
add(534,'وهنا انقسم أصحاب هذا الفرق ثلاثة أقسام: قسم غابوا بأفعالهم وحركاتهم عن فعل الربّ تعالى وقضائه، مع إيمانهم به؛ وقسم غابوا بفعل الربّ وتفرّده بالحكم والمشيئة عن أفعالهم وحركاتهم؛ وقسم أعطوا المراتب حقّها، فآمنوا بفعل الربّ وقدره ومشيئته، وتفرّده بالحكم والقضاء، وشهدوا وقوع الأفعال من فاعليها، واستحقاقهم عليها المدح والذمّ والثواب والعقاب.','Здесь обладатели этого различения разделились на три группы. Одни, будучи поглощены своими действиями и движениями, перестали замечать действие Господа Всевышнего и Его решение, хотя верят в него. Другие, будучи поглощены действием Господа и Его единоличностью в решении и воле, перестали замечать свои действия и движения. Третьи отдали каждому уровню должное: уверовали в действие Господа, Его предопределение и волю, Его единоличность в решении и суде и созерцали совершение действий теми, кто их совершает, и то, что за них они заслуживают похвалы, порицания, награды и наказания.')
add(534,'فالفريق الأوّل: يغلب عليهم الفرق الطبعيّ، إذ لم يصعدوا إلى مشاهدة الحكم.','В первой группе преобладает естественное различение, поскольку они не поднялись до созерцания решения.')
add(534,'والفريق الثاني: يغلب عليهم حال الجمع، وهو شهود قدر الربّ تعالى ومشيئته وتدبيره لخلقه، فتجتمع قلوبهم على شهود أفعاله بعد أن كانت','Во второй группе преобладает состояние собранности — созерцание предопределения Господа Всевышнего, Его воли и управления творением. Их сердца сосредоточиваются на созерцании Его действий после того, как были',False)
